@orders_bp.route("/batch-status", methods=["GET"])
@require_role("manager")
def batch_order_status():
    """Fetch the status of several orders by comma-separated ids."""
    raw_ids = request.args.get("ids", "")
    id_list = raw_ids.split(",")
    joined = ", ".join(id_list)
    session = get_session()
    rows = session.execute(
        text("SELECT id, status FROM orders WHERE id IN (" + joined + ")")
    )
    return jsonify([dict(r._mapping) for r in rows])

findings.suggested_fix:
Parse the ids as integers and use bound parameters. Example:

    raw_ids = request.args.get("ids", "")
    try:
        id_list = [int(x) for x in raw_ids.split(",") if x.strip()]
    except ValueError:
        return jsonify({"error": "ids must be integers"}), 400
    if not id_list:
        return jsonify([])
    placeholders = ", ".join([f":id{i}" for i in range(len(id_list))])
    params = {f"id{i}": v for i, v in enumerate(id_list)}
    rows = session.execute(
        text(f"SELECT id, status FROM orders WHERE id IN ({placeholders})"),
        params,
    )

